    @pytest.mark.parametrize('stage', ['learner', 'configuration'])
    def test_failed_refit_does_not_mix_samples(kind, stage):
        model = estimator(kind, dataset(kind)).fit()
        first = estimate(model, kind, False)
        new_data = dataset(kind)
